refs.extend([dict(id='journal',title='Internal Parametricity for Cubical Type Theory',authors='Evan Cavallo; Robert Harper',year=2021,url='https://lmcs.episciences.org/8651',locator='LMCS 17(4:5), Sections 5–7 and Appendix A: formalisms, model and later discussion.'),dict(id='agda2024',title='Internal and Observational Parametricity for Cubical Agda',authors='Antoine Van Muylder; Andreas Nuyts; Dominique Devriese',year=2024,url='https://hott-uf.github.io/2024/abstracts/HoTTUF_2024_paper_13.pdf',locator='Authors’ HoTT/UF 2024 abstract: Agda --bridges implementation and internal parametricity results.')])
issue='The source does not fix the target meant by ordinary type theory, its universes and type formers, or a complete grammar for the common function-free fragment. In particular, function types hidden in universe codes and which path or inductive types are admitted affect the claim. It also does not specify whether an effective proof translation beyond derivability conservativity is required. A chosen base calculus or an arbitrary smaller fragment must not be silently substituted.'
notes=['Recovered the conjecture immediately preceding the damaged excerpt: Γ and A, rather than the whole proof, exclude function types.','Distinguished derivability in the base calculus from validity in a model and from a proof-translation algorithm.','Preserved missing base calculus, common-fragment grammar and universe conventions.','Removed suggested semantic approaches and checked the expanded 2021 paper and 2024 implementation result.']
save(i,dict(title='Conservativity of internal parametricity for function-free judgments',formal='Does adding the source’s internal-parametricity structure preserve all inhabitation judgments whose context and result type use no function types? The proposed form is: for every context Γ and type A in a common function-free fragment of the base and parametric theories, if Γ⊢M:A is derivable in the parametric extension for some term M, then Γ⊢N:A is derivable in the base theory for some term N. The restriction is on Γ and A, not on the intermediate types or constructions in the extended derivation. The source calls the destination ordinary type theory but does not fully specify that calculus or the common fragment, so this is a recovered conjecture schema rather than a complete formal benchmark.',definitions='A context Γ is an ordered list x₁:A₁,…,x_j:A_j of typed variables, where A_i may depend on earlier variables. A judgment Γ⊢M:A asserts that M is a term of type A under those assumptions. Inhabitation means the existence of such a term. A dependent function type Π(x:B).C classifies functions taking x:B to a result in C, which may depend on x; B→C is the nondependent case. The source excludes function types from the statement and assumptions of the proposed conservative fragment. It does not give an inductive grammar deciding all permitted type expressions, including expressions represented inside universes. Internal parametricity adds types and terms expressing relational behavior inside the theory itself. In the paper, paths represent equality-like structure and bridges represent relations; the extension includes bridge and Gel constructions in addition to cartesian cubical structure. A common fragment must contain expressions meaningful in the target calculus, not just extended types that happen to lack an arrow symbol. Conservativity for the stated fragment would preserve existence of inhabitants; it does not demand that the extended term M itself be a term of the smaller language, or that M and N be judgmentally equal. A syntactic proof transformation would compute a base derivation from an extended derivation. Semantic validity in one model, consistency and canonicity for a particular closed type are different claims and do not by themselves state this general derivability property. Which of the cubical, universe, path and inductive rules are retained in the base remains part of the missing specification.',question_type='yes_no',answer_criterion='For fully specified source and target calculi and the intended common fragment, prove that every extended derivation of an inhabitation judgment in the fragment has a base derivation, or exhibit a judgment in that same fragment which is derivable only in the extension. If an effective translation is part of the intended target, its input, output and derivation-preservation requirement must also be fixed. The current source does not determine all these choices. A model construction alone or a result for a chosen smaller class of judgments does not certify the whole schema.',context_blocks=[dict(title='Why the function-free restriction appears',text='The conference paper explicitly warns that unrestricted conservativity fails. It gives a statement asserting that every map from a universe to the booleans takes the same value at the unit and empty types: this is provable using parametricity but fails in classical cubical sets. The proposed function-free restriction follows that example.',citation='primary'),dict(title='The proof may use the richer theory',text='The intended benefit is to reason with internal parametricity while obtaining a conclusion available in the original language. Restricting every step of the proof to the base language would remove that distinction and would not express the conjecture in the concluding paragraph.',citation='primary'),dict(title='Later formalisms do not identify this target for us',text='The 2021 expanded paper develops formal and computational presentations and a model of internal parametricity. The checked sections do not supply a syntactic conservativity theorem matching the conference question’s unspecified ordinary target and function-free fragment.',citation='journal'),dict(title='Implementation progress is a different guarantee',text='The 2024 authors’ abstract describes Agda --bridges, mechanized internal-parametricity theorems and compatibility with the existing cubical library. Supporting base proofs in an extension does not establish the reverse statement that every new proof of a common judgment has a base proof.',citation='agda2024')],why='Would clarify which conclusions proved using internal relational principles can be transferred back to an ordinary type theory, and thus how much proof strength the added parametricity contributes on a restricted language.',references=refs,progress=[dict(date='2020',text='The conference conclusion proposes conservativity for contexts and result types without function types, after identifying failure for unrestricted statements.',citation='primary'),dict(date='2021',text='The expanded paper supplies richer formal presentations and semantics but does not provide the matching syntactic theorem in the checked discussion.',citation='journal'),dict(date='2024',text='An implementation and mechanized internal-parametricity results are reported for Cubical Agda; these do not settle the reverse conservativity assertion.',citation='agda2024')],status='uncertain',status_note='Read the exact conference conjecture, checked the expanded LMCS formalisms and discussion, and the later authors’ implementation abstract. Conservativity searches through 12 September 2026 found no matching resolution. The source’s target calculus and fragment remain insufficiently specified.',model_self_contained=False,requires_context=True,statement_review=dict(status='needs_specification',reviewed_on=DATE,notes=notes,remaining_issue=issue),review_note=issue,importance=dict(score=c['importance']['score'],method='editorial',reason='A foundational transfer-of-proof-strength question for internal parametricity and dependent type theory; existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['The conjecture concerns proofs made in a type theory with internal parametricity.','It asks whether an inhabited type already has an inhabitant in the base theory when the assumptions and result type contain no function types.','The richer derivation itself may use function types and parametricity.','Unrestricted conservativity is already ruled out by the source, but the restricted claim lacks an exact base calculus and fragment grammar.','Later semantic and implementation developments are distinguished from the missing syntactic conservativity theorem.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal','agda2024'])),notes=notes,checked_sources=[r['url'] for r in refs],state='improved_unfinished')
